    field_info: Optional[FieldInfo] = None,
    alias: Optional[str] = None,
    mode: Literal["validation", "serialization"] = "validation",
    version: Literal["1", "auto"] = "auto",
) -> ModelField:
    class_validators = class_validators or {}

    # Extract primary type if Annotated is used and field_info is not explicitly provided
    if field_info is None and get_origin(type_) is not None and get_origin(type_) is not type_:
